<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$client=(int)($_GET['client_id']??$_POST['client_id']??0);$project=(int)($_GET['project_id']??$_POST['project_id']??0);$proposal=(int)($_GET['proposal_id']??$_POST['proposal_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){$c=$db->prepare('SELECT id,lead_id,name,email FROM clients WHERE id=? AND status<>"archived"');$c->execute([$client]);$clientRow=$c->fetch();if(!$clientRow)exit('Valid client is required.');$items=[];$descs=$_POST['description']??[];$qtys=$_POST['quantity']??[];$prices=$_POST['unit_price']??[];foreach($descs as $n=>$desc){$desc=trim((string)$desc);$q=(float)($qtys[$n]??1);$price=(float)($prices[$n]??0);if($desc!==''&&$q>0)$items[]=[$desc,$q,$price,round($q*$price,2)];}if(!$items)exit('At least one invoice item is required.');$subtotal=round(array_sum(array_column($items,3)),2);$discount=max(0,(float)($_POST['discount']??0));$taxRate=max(0,(float)($_POST['tax_rate']??0));$tax=round(max(0,$subtotal-$discount)*$taxRate/100,2);$total=round(max(0,$subtotal-$discount)+$tax,2);$token=bin2hex(random_bytes(32));$num='DWS-INV-'.date('Ym').'-'.str_pad((string)((int)$db->query("SELECT COUNT(*) FROM invoices WHERE DATE_FORMAT(created_at,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')")->fetchColumn()+1),4,'0',STR_PAD_LEFT);$leadId=$clientRow['lead_id']?:null;$db->beginTransaction();try{$q=$db->prepare('INSERT INTO invoices(client_id,project_id,proposal_id,lead_id,invoice_number,public_token,title,issue_date,due_date,status,currency,subtotal,discount,tax_rate,tax_amount,tax,total,amount_paid,balance_due,notes,terms) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$client,$project?:null,$proposal?:null,$leadId,$num,$token,trim($_POST['title']??'Invoice'),$_POST['issue_date']?:date('Y-m-d'),$_POST['due_date']?:null,'draft',$_POST['currency']?:'USD',$subtotal,$discount,$taxRate,$tax,$tax,$total,0,$total,trim($_POST['notes']??''),trim($_POST['terms']??'')]);$invoiceId=(int)$db->lastInsertId();$qi=$db->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit_price,line_total,amount,sort_order) VALUES(?,?,?,?,?,?,?)');foreach($items as $n=>$it)$qi->execute([$invoiceId,$it[0],$it[1],$it[2],$it[3],$it[3],$n]);if($project)$db->prepare('UPDATE client_projects SET invoice_id=? WHERE id=? AND client_id=?')->execute([$invoiceId,$project,$client]);if($proposal&&$db->query("SHOW TABLES LIKE 'invoice_events'")->fetch())$db->prepare('INSERT INTO invoice_events(invoice_id,event_type,description) VALUES(?,?,?)')->execute([$invoiceId,'created','Invoice created from proposal/CMS']);$db->commit();header('Location: invoice-view.php?token='.urlencode($token));exit;}catch(Throwable $ex){$db->rollBack();http_response_code(500);exit('Unable to create invoice: '.($ex->getCode()==='23000'?'duplicate or invalid reference':'database error'));}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New Invoice</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card shadow-sm"><div class="card-body"><h1 class="h4">Create Invoice</h1><form method="post"><input type="hidden" name="client_id" value="<?=$client?>"><input type="hidden" name="project_id" value="<?=$project?>"><input type="hidden" name="proposal_id" value="<?=$proposal?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Title</label><input class="form-control" name="title" value="Professional Services Invoice"></div><div class="col-md-3"><label class="form-label">Issue date</label><input class="form-control" type="date" name="issue_date" value="<?=date('Y-m-d')?>"></div><div class="col-md-3"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date"></div><div class="col-md-3"><label class="form-label">Currency</label><select class="form-select" name="currency"><option>USD</option><option>NGN</option><option>GBP</option><option>EUR</option></select></div></div><hr><h2 class="h6">Line items</h2><div id="items"><div class="row g-2 mb-2 item"><div class="col-md-6"><input class="form-control" name="description[]" placeholder="Description" required></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" min="0" name="quantity[]" value="1"></div><div class="col-md-3"><input class="form-control" type="number" step="0.01" min="0" name="unit_price[]" value="0"></div></div></div><button class="btn btn-outline-secondary mb-3" type="button" onclick="items.insertAdjacentHTML('beforeend',document.querySelector('.item').outerHTML)">Add item</button><div class="row g-3"><div class="col-md-3"><label class="form-label">Discount</label><input class="form-control" type="number" step="0.01" min="0" name="discount" value="0"></div><div class="col-md-3"><label class="form-label">Tax %</label><input class="form-control" type="number" step="0.001" min="0" name="tax_rate" value="0"></div></div><textarea class="form-control my-3" name="notes" placeholder="Notes"></textarea><textarea class="form-control mb-3" name="terms" placeholder="Terms & Conditions"></textarea><button class="btn btn-dark">Create Draft Invoice</button></form></div></div></main></body></html>